package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"reflect"
	"sort"
	"strings"
	"testing"

	"api-gateway/openapi"
)

// The Swagger document is generated by swag from comments, which the compiler
// does not check. These tests hold the generated document to the code.

type swaggerDoc struct {
	Swagger string `json:"swagger"`
	Paths   map[string]map[string]struct {
		Parameters []map[string]any `json:"parameters"`
		Responses  map[string]any   `json:"responses"`
	} `json:"paths"`
	Definitions map[string]struct {
		Required   []string       `json:"required"`
		Properties map[string]any `json:"properties"`
	} `json:"definitions"`
}

func loadSwagger(t *testing.T) swaggerDoc {
	t.Helper()
	var d swaggerDoc
	if err := json.Unmarshal(openapi.JSON, &d); err != nil {
		t.Fatalf("swagger.json: %v (run make swagger)", err)
	}
	if d.Swagger != "2.0" {
		t.Fatalf("swagger version %q", d.Swagger)
	}
	return d
}

func sortedCopy(in []string) []string {
	out := append([]string(nil), in...)
	sort.Strings(out)
	return out
}

func TestSwaggerMatchesHandlers(t *testing.T) {
	d := loadSwagger(t)
	f := newFake()
	seed(f, 1)
	s, _ := newServer(f, nil)
	h := s.Handler()

	// The documented paths are exactly the data routes, and each is served.
	routes := map[string][]string{
		"/api/v1/gpus":                gpuParams,
		"/api/v1/gpus/{id}/telemetry": telemetryParams,
	}
	if len(d.Paths) != len(routes) {
		t.Errorf("swagger documents %d paths, the gateway serves %d data routes", len(d.Paths), len(routes))
	}
	for path, allowed := range routes {
		op, ok := d.Paths[path]["get"]
		if !ok {
			t.Errorf("GET %s has no @Router annotation", path)
			continue
		}
		var query []string
		for _, p := range op.Parameters {
			if p["in"] == "query" {
				query = append(query, p["name"].(string))
			}
			// Swagger UI pre-fills these into "Try it out"; every parameter is optional.
			for _, k := range []string{"default", "example", "x-example"} {
				if _, ok := p[k]; ok {
					t.Errorf("GET %s: parameter %s has %s", path, p["name"], k)
				}
			}
			// limit is optional and uncapped: leaving it out returns everything.
			if p["name"] == "limit" && (p["required"] == true || p["maximum"] != nil ||
				!strings.Contains(p["description"].(string), "all of them when omitted")) {
				t.Errorf("GET %s: limit must be optional, uncapped and say so: %v", path, p)
			}
		}
		if got, want := sortedCopy(query), sortedCopy(allowed); !reflect.DeepEqual(got, want) {
			t.Errorf("GET %s: @Param query %v, handler accepts %v", path, got, want)
		}
		url := strings.ReplaceAll(path, "{id}", FormatGPUID(gpuA))
		if rec := get(t, h, url, nil); rec.Code != http.StatusOK {
			t.Errorf("GET %s: %d", url, rec.Code)
		}
	}
	if _, ok := d.Paths["/api/v1/gpus/{id}/telemetry"]["get"].Responses["404"]; !ok {
		t.Error("telemetry 404 not documented")
	}

	// Each schema lists exactly the fields the Go type encodes, required unless omitempty.
	for name, v := range map[string]any{
		"GPU": gpuJSON{}, "GPUList": gpuList{}, "TelemetryEntry": entryJSON{}, "TelemetryList": telemetryList{}, "Error": errorBody{},
	} {
		def, ok := d.Definitions[name]
		if !ok {
			t.Errorf("definition %s missing (its @name annotation?)", name)
			continue
		}
		var fields, required, props []string
		rt := reflect.TypeOf(v)
		for i := range rt.NumField() {
			n, opts, _ := strings.Cut(rt.Field(i).Tag.Get("json"), ",")
			fields = append(fields, n)
			if opts != "omitempty" {
				required = append(required, n)
			}
		}
		for k := range def.Properties {
			props = append(props, k)
		}
		if got, want := sortedCopy(props), sortedCopy(fields); !reflect.DeepEqual(got, want) {
			t.Errorf("definition %s: properties %v, type encodes %v (run make swagger)", name, got, want)
		}
		if got, want := sortedCopy(def.Required), sortedCopy(required); !reflect.DeepEqual(got, want) {
			t.Errorf("definition %s: required %v, want the non-omitempty fields %v", name, got, want)
		}
	}
	if d.Definitions["TelemetryEntry"].Properties["value"].(map[string]any)["x-nullable"] != true {
		t.Error("value must be x-nullable (NaN and Inf encode as null)")
	}

}

func TestSwaggerAndDocsServed(t *testing.T) {
	s, _ := newServer(newFake(), nil)
	h := s.Handler()

	for path, want := range map[string]struct {
		contentType string
		body        []byte
	}{
		"/api/v1/swagger.json": {"application/json", openapi.JSON},
		"/api/v1/swagger.yaml": {"application/yaml", openapi.YAML},
	} {
		rec := get(t, h, path, nil)
		if rec.Code != 200 || rec.Header().Get("Content-Type") != want.contentType || !bytes.Equal(rec.Body.Bytes(), want.body) {
			t.Errorf("%s: %d %q", path, rec.Code, rec.Header().Get("Content-Type"))
		}
	}
	rec := get(t, h, "/api/v1/docs", nil)
	if rec.Code != 200 || !strings.HasPrefix(rec.Header().Get("Content-Type"), "text/html") ||
		!strings.Contains(rec.Body.String(), `url: "swagger.json"`) {
		t.Fatalf("docs: %d %q", rec.Code, rec.Body.String())
	}
	post := httptest.NewRecorder()
	h.ServeHTTP(post, httptest.NewRequest(http.MethodPost, "/api/v1/swagger.json", nil))
	if post.Code != http.StatusMethodNotAllowed {
		t.Fatalf("POST swagger.json: %d", post.Code)
	}
}
